def is_capitalized(s):
    # No symbols, no numbers
    for i in range(len(s)):
        c = s[i]
        if not c.isalpha():
            if not (i == len(s)-1 and c == '.'):
                return False
    if s.endswith('.'):
        s = s[:-1]
    # No uppercase except first letter
    for c in s[1:]:
        if not c.islower():
            return False
    return s[0].isupper()

